const g = items[0].json;
const params = $('Parâmetros').first().json;

const partes = new Intl.DateTimeFormat('en-US', {
  timeZone: 'America/Sao_Paulo', hour: 'numeric', hour12: false, weekday: 'short',
}).formatToParts(new Date());
const hora = parseInt(partes.find((p) => p.type === 'hour').value, 10);
const diaSemana = partes.find((p) => p.type === 'weekday').value;

const diaUtil = diaSemana !== 'Sun'; // permite sábado — só domingo fica de fora
const dentroDaJanela = diaUtil && hora >= 9 && hora < 18;

const limite = g.limite != null ? parseInt(g.limite, 10) : 0;
const usado = g.usado != null ? parseInt(g.usado, 10) : 0;
const cotaRestante = Math.max(limite - usado, 0);

let bloqueadoMotivo = null;
if (!g.id) bloqueadoMotivo = 'campanha_inexistente';
else if (g.pausada) bloqueadoMotivo = 'campanha_pausada';
else if (!dentroDaJanela) bloqueadoMotivo = 'fora_da_janela';
else if (cotaRestante <= 0) bloqueadoMotivo = 'cota_esgotada';

const tamanhoLote = bloqueadoMotivo ? 0 : Math.min(params.tamanho_lote_padrao, cotaRestante);

return [{
  json: {
    campanha_id: params.campanha_id,
    modo_whitelist: !!g.modo_whitelist,
    template_wa: g.template_wa,
    tamanho_lote: tamanhoLote,
    bloqueado_motivo: bloqueadoMotivo,
  },
}];

// Cada campanha usa seu próprio template aprovado — o nome vem de campanhas.template_wa,
// não mais fixo em variável de ambiente. Templates sem variável nenhuma (followup2/3/4)
// mandam o corpo sem "components".
const PARAMETROS_POR_TEMPLATE = {
  convite_bni_workshop_ady: (it) => [
    { type: 'text', text: it.json.nome || '' },
    { type: 'text', text: '1 de setembro às 20h' },
    { type: 'text', text: 'https://www.useady.com.br/workshop' },
  ],
  followup1_workshop: (it) => [
    { type: 'text', text: it.json.nome || '' },
  ],
  followup2_workshop: () => [],
  followup3_workshop: () => [],
  followup4_workshop: () => [],
};

const templateNome = $('Avaliar Guardas').first().json.template_wa;
const montarParametros = PARAMETROS_POR_TEMPLATE[templateNome];
if (!montarParametros) {
  throw new Error(`Template WhatsApp desconhecido: "${templateNome}". Adicione ele em PARAMETROS_POR_TEMPLATE.`);
}

return items.map((it) => {
  const parametros = montarParametros(it);
  const template = {
    name: templateNome,
    language: { code: $env.WA_TEMPLATE_LANG },
  };
  if (parametros.length > 0) {
    template.components = [{ type: 'body', parameters: parametros }];
  }
  const corpo = {
    messaging_product: 'whatsapp',
    to: (it.json.destino || '').replace('+', ''),
    type: 'template',
    template,
  };
  return { json: { ...it.json, corpoJson: JSON.stringify(corpo) } };
});

const claimed = $('Claim Atômico do Lote (WhatsApp)').all();

const CODIGOS_PERMANENTES = new Set(['131026']);
const CODIGOS_QUALIDADE = new Set(['131048']);

function backoffSql() {
  return `UPDATE envios SET
            status = CASE WHEN tentativas >= 5 THEN 'falha' ELSE 'pendente' END,
            erro_tipo = CASE WHEN tentativas >= 5 THEN 'permanente' ELSE 'temporario' END,
            erro_codigo = $2, erro_mensagem = $3,
            agendado_para = CASE tentativas
              WHEN 1 THEN now() + interval '5 minutes'
              WHEN 2 THEN now() + interval '15 minutes'
              WHEN 3 THEN now() + interval '1 hour'
              WHEN 4 THEN now() + interval '4 hours'
              ELSE now() + interval '12 hours'
            END,
            atualizado_em = now()
          WHERE id = $1;`;
}

const out = [];
for (let i = 0; i < items.length; i++) {
  const resp = items[i].json;
  const envio = claimed[i].json;
  const statusCode = resp.statusCode;
  const body = resp.body || {};

  let sql;
  let params;
  let pausarCampanha = false;

  if (statusCode >= 200 && statusCode < 300) {
    const providerMessageId = (body.messages && body.messages[0] && body.messages[0].id) || null;
    sql = 'UPDATE envios SET status=\'enviado\', provider_message_id=$2, enviado_em=now(), atualizado_em=now() WHERE id=$1;';
    params = [envio.id, providerMessageId];
  } else {
    const err = body.error || {};
    const errorCode = err.code != null ? String(err.code) : 'desconhecido';
    const errorMsg = err.message || `HTTP ${statusCode}`;

    if (CODIGOS_PERMANENTES.has(errorCode)) {
      sql = `WITH alvo AS (
               UPDATE envios SET status='falha', erro_tipo='permanente', erro_codigo=$2, erro_mensagem=$3, atualizado_em=now()
               WHERE id=$1 RETURNING destino
             )
             INSERT INTO supressao (canal, destino, motivo)
             SELECT 'whatsapp', destino, 'invalido' FROM alvo
             ON CONFLICT (canal, destino) DO NOTHING;`;
      params = [envio.id, errorCode, errorMsg];
    } else if (errorCode === '131047') {
      sql = 'UPDATE envios SET status=\'falha\', erro_tipo=\'permanente\', erro_codigo=$2, erro_mensagem=$3, atualizado_em=now() WHERE id=$1;';
      params = [envio.id, errorCode, errorMsg];
    } else if (CODIGOS_QUALIDADE.has(errorCode)) {
      sql = backoffSql();
      params = [envio.id, errorCode, errorMsg];
      pausarCampanha = true;
    } else {
      sql = backoffSql();
      params = [envio.id, errorCode, errorMsg];
    }
  }

  out.push({ json: { sql, params, pausarCampanha, campanha_id: envio.campanha_id } });
}
return out;

